import{_ as n,o as i,c as t,a3 as s}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"Eigene Seitenleisten-Verknüpfungen","description":"UIX-Einträge in der Home-Assistant-Seitenleiste mit internen Weiterleitungszielen erstellen.","frontmatter":{"title":"Eigene Seitenleisten-Verknüpfungen","description":"UIX-Einträge in der Home-Assistant-Seitenleiste mit internen Weiterleitungszielen erstellen."},"headers":[],"relativePath":"projects/uix/using/custom-sidebar-panels.md","filePath":"projects/uix/using/custom-sidebar-panels.md","lastUpdated":1793447386000}'),r={name:"projects/uix/using/custom-sidebar-panels.md"};function a(l,e,o,d,u,c){return i(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="eigene-seitenleisten-verknupfungen" tabindex="-1">Eigene Seitenleisten-Verknüpfungen <a class="header-anchor" href="#eigene-seitenleisten-verknupfungen" aria-label="Permalink to &quot;Eigene Seitenleisten-Verknüpfungen&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Verfügbar ab UIX 9.0.0-beta.6</p><p>Diese Funktion gehört zur Vorschau auf <code>dev</code>, nicht zur stabilen Basis 8.4.0. Abgeglichen am 31.10.2026 mit der <a href="https://github.com/Lint-Free-Technology/uix/blob/e6fb84dd715ea4bac9a330357705897ea8d44690/docs/source/using/custom-sidebar-panels.md" target="_blank" rel="noreferrer">englischen Quelle</a>.</p></div><p>UIX kann eigene Einträge zur Home-Assistant-Seitenleiste hinzufügen, die direkt auf eine andere Home-Assistant-Seite weiterleiten. Das eignet sich für häufig verwendete Seiten, die sonst erst über Einstellungen oder ein anderes Panel erreichbar sind.</p><p>Öffne <strong>Einstellungen → Geräte &amp; Dienste → UI eXtension → Konfigurieren</strong> und wähle <strong>Manage custom sidebar panels</strong> (eigene Seitenleisten-Panels verwalten). Wähle beim Hinzufügen ein Symbol, gib einen Titel ein und bestimme das Ziel mit der Navigationsauswahl.</p><p>Aktiviere <strong>Admin required</strong>, wenn das Seitenleisten-Panel nur für Administratorkonten zugänglich sein soll.</p><p>Als Ziele sind ausschließlich Navigationspfade innerhalb derselben Home-Assistant-Instanz zulässig. Eigene Seitenleisten-Panels leiten nicht auf externe Webseiten weiter.</p><p>Jedes Panel erhält eine feste interne URL, die UIX verwaltet. Titel, Symbol und Ziel lassen sich ändern, ohne das Panel neu anzulegen. Beim Löschen verschwindet der Seitenleisteneintrag sofort.</p><div class="tip custom-block"><p class="custom-block-title">Reihenfolge der Seitenleiste</p><p>Jeder Benutzer kann die <a href="https://www.home-assistant.io/dashboards/dashboards/#reorganizing-items-in-the-sidebar" target="_blank" rel="noreferrer">Seitenleisteneinträge in seinem Home-Assistant-Profil umsortieren oder ausblenden</a>.</p></div><div class="info custom-block"><p class="custom-block-title">Verhalten der Weiterleitung</p><p>Ein eigenes Seitenleisten-Panel ist eine Weiterleitung, keine Kopie der Zielseite. Beim Auswählen ersetzt UIX die Panel-URL durch das konfigurierte Ziel. Dadurch entsteht im Browserverlauf kein zusätzlicher Weiterleitungsschritt.</p></div>',9)])])}const m=n(r,[["render",a]]);export{p as __pageData,m as default};
